entries[62338] = { ["name"] = "Runenbarriere", ["text"] = "Sofort\nEin Schild aus Runenmacht umgibt den Zaubernden, welcher den erlittenen Schaden um 50% verringert und Angreifern 2000 Arkanschaden zufügt." }
entries[62339] = { ["name"] = "Schmettern", ["text"] = "Wirken in 3 sek. 2 sek. Abklingzeit\nFügt allen Feinden in einem kegelförmigen Bereich von 10 Metern vor dem Zaubernden 37000 bis 43000 körperlichen Schaden zu." }
