entries[62343] = { ["name"] = "Hitze", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht alle nahen Eisenkonstrukte mit intensiver Hitze, was ihr Bewegungstempo um 5 und ihr Tempo um 5 erhöht. Dieser Effekt ist bis zu 10-mal stapelbar. Wenn der Effekt 10 Stapel erreicht hat, wird das betroffene Eisenkonstrukt schmelzen." }
entries[62344] = { ["name"] = "Fäuste aus Stein", ["text"] = "Wirken in 2.5 sek. 10 sek. Abklingzeit\nDie Steinfäuste verlangsamen das Bewegungstempo des Zaubernden um 20% und erhöhen den verursachten Schaden um 250%. Zusätzlich haben die vernichtenden Angriffe die Chance, dem Ziel die Knochen zu brechen, was dessen Chance zu blockieren, auszuweichen oder zu parieren 20 Sek. lang um 100% senkt.\n(5s Abklingzeit)" }
entries[62345] = { ["name"] = "Rammen", ["text"] = "40 Energie 15 Meter Reichweite\nSofort\nRammt alle Feinde, die sich vor dem Verwüster befinden, verursacht 22501 bis 27501 Schaden und stößt sie zurück. Verursacht zudem bei Gebäuden 2850 bis 3150 Belagerungsschaden." }
entries[62346] = { ["name"] = "Volldampf voraus!", ["text"] = "40 Energie 70 Meter Reichweite\nSofort 15 sek. Abklingzeit\nSchaltet die Dampfmaschine eine kurze Zeit lang in den Overdrive und lässt sie nach vorne schnellen. Verursacht dabei Belagerungsschaden und schleudert Gegner zurück." }
entries[62347] = { ["name"] = "Netherschock", ["text"] = "20 Meter Reichweite\nSofort 40 sek. Abklingzeit\nPeitscht sofort nach einem Feind, unterbricht das Wirken von Zaubern und verhindert 2 Sek. lang, dass ein Zauber dieser Art gewirkt werden kann." }
